/**
 * A Family Record
 * ---------------
 * The generations from Adam are recorded, and Jared fathers Enoch, who walks in a line of long-lived fathers and sons. Stage: a family register in a tent at dusk, names spoken aloud, a child held up; lamplight on a written scroll, the long line of ancestors behind.
 *
 * Palette 0x1a2a1a → 0x060402 · light: dawn · hero: scroll
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./enoch-kit.js.
 */

import { THREE, createScene, tent, scroll, person } from './enoch-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 337138786, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents */
    tent(W, group, 1.8, 0, -17.8, 1.11, 0xd8c8a0, W.r() * 6);
    tent(W, group, 0.9, 0, -8.1, 1.38, 0x8a6a44, W.r() * 6);
    tent(W, group, 1.4, 0, -14.2, 1.26, 0x8a6a44, W.r() * 6);
    tent(W, group, -11.0, 0, -4.1, 0.93, 0xa8704a, W.r() * 6);
    tent(W, group, -23.0, 0, -2.4, 0.95, 0xd8c8a0, W.r() * 6);

    /* hero: the scroll */
    scroll(W, group, 0, 0.9, 0, 1.2, { ry: 0.5 });
    W.disc([0, 4, -10], 4, 0x223722, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a2a1a, ry: 0.70, s: 1.11 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, ry: -0.60, s: 1.05 });

    return W.finish();
}

export default { build };
